import collections,re,sys,json
from datetime import date
POS={"happy","great","good","proud","calm","excited","grateful","energized"}
NEG={"tired","stressed","anxious","sad","angry","bored","overwhelmed","worried"}
STOP={"about","their","there","would","which","other","these","today"}
def themes(entries,n=5):
    w=collections.Counter(x for e in entries for x in re.findall(r"[a-z]{5,}",e.lower()) if x not in STOP)
    return w.most_common(n)
def mood(e):
    t=re.findall(r"[a-z]+",e.lower());return sum(x in POS for x in t)-sum(x in NEG for x in t)
def habits(entries):
    keys=["gym","run","sleep","study","code","meditat"]
    out={}
    for k in keys:
        d=[(mood(e)) for e in entries if k in e.lower()]
        if d: out[k]={"days":len(d),"avg_mood":round(sum(d)/len(d),2)}
    return out
def report(entries):
    return {"themes":themes(entries),"mood_trend":[mood(e) for e in entries],"habit_mood":habits(entries)}
if __name__=="__main__":
    print(json.dumps(report(sys.stdin.read().splitlines()),indent=1))

def tags(entries):
